export const title = "Analysis Video Settings";
export const html = "<h1>Analysis Video Settings</h1>\n      <hr class=\"rule\" />\n      <h2>Camera Video Reception Setup</h2>\n      <p>To receive and analyze video from a camera on the AI Bridge, you first need to configure the camera's connection information.</p>\n      <p>Click the <strong>Video Stream</strong> menu in the sidebar navigation to display the setup menu for receiving video from cameras in the main content area.</p>\n      \n<div class=\"figure\">\n<div class=\"app-window\">\n  <div class=\"app-topnav\">\n    <div class=\"app-logo\">&#9679; Indo AI <span style=\"font-weight:400;opacity:.7;\">AI Bridge</span></div>\n    <div>&#9776; &nbsp; Device 98E838</div>\n    <div class=\"app-right\">Arm/Disarm <span style=\"background:#2f9e6e;border-radius:10px;padding:1px 8px;\">Arm</span> <span class=\"btn small\">&#9633; Video Preview</span> admin &#9660;</div>\n  </div>\n  <div class=\"app-body\">\n    <div class=\"app-sidebar-nav\">\n      <div class=\"grp\">Video</div>\n      <div class=\"item\">Video Input &#9656;</div>\n      <div class=\"item active\">&nbsp;&nbsp;Video Stream</div>\n      <div class=\"item\">&nbsp;&nbsp;False Alarm Reduction</div>\n      <div class=\"item\">Display &#9656;</div>\n      <div class=\"item\">Event Rule List</div>\n      <div class=\"grp\">System Settings</div>\n      <div class=\"item\">Network &#9656;</div>\n      <div class=\"item\">System &#9656;</div>\n      <div class=\"item\">License Management</div>\n      <div class=\"item\">Cloud Service</div>\n      <div class=\"grp\">App Settings</div>\n      <div class=\"item\">Explore AI Apps</div>\n      <div class=\"item\">Active AI Apps &#9656;</div>\n      <div class=\"item\">System Event Settings</div>\n    </div>\n    <div class=\"app-main\">\n\n      <div class=\"app-breadcrumb\">Home / Video Input / Video Stream</div>\n      <div class=\"app-h\">Video Stream</div>\n      <div class=\"app-panel\">\n        <div class=\"usage-row\"><span class=\"lbl\">AI Engine Resource &#9432;</span><div class=\"usage-bar\"><span style=\"width:26%;\"></span></div><span class=\"val\">1044 / 4200</span></div>\n        <div class=\"usage-row\"><span class=\"lbl\">Video Decoding Resource &#9432;</span><div class=\"usage-bar\"><span style=\"width:16%;\"></span></div><span class=\"val\">160 / 1000</span></div>\n        <div class=\"usage-row\"><span class=\"lbl\">Video Resolution Resource &#9432;</span><div class=\"usage-bar\"><span style=\"width:15%;\"></span></div><span class=\"val\">148 / 1000</span></div>\n      </div>\n      <div class=\"app-panel\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;\">\n          <span class=\"btn small\">&#9432; Stream Info</span>\n          <span><span class=\"btn small\">&#128269; Search Cameras</span> <span class=\"btn small primary\">&#9998; Edit Video</span></span>\n        </div>\n        <table class=\"app-table\">\n          <tr><th></th><th>Name</th><th>Status</th><th>Res / FPS</th><th>URL</th><th></th></tr>\n          <tr><td>1</td><td>W.O Bldg.</td><td><span class=\"badge\">Connected</span> 1920x1080</td><td>8.0fps</td><td>rtsp://192.168.101.7:5554/video/1080p.mp4</td><td>&#9881; &#9776; <span class=\"btn small\">+</span></td></tr>\n          <tr><td>2</td><td>LPR PL</td><td><span class=\"badge\">Connected</span> 1920x1080</td><td>36.1fps</td><td>rtsp://192.168.101.7:5554/video/lpr_pl.mp4</td><td>&#9881; <span class=\"btn small\">+</span></td></tr>\n          <tr><td>3</td><td>AES</td><td><span class=\"badge\">Connected</span> 1920x1080</td><td>3.9fps</td><td>rtsp://192.168.101.7:5554/video/aes3_15.mp4</td><td>&#9835; &#9834; <span class=\"btn small\">+</span></td></tr>\n          <tr><td>4</td><td>\u2014</td><td colspan=\"3\"></td><td><span class=\"btn small\">Configure AI App</span></td></tr>\n          <tr><td>5</td><td>\u2014</td><td colspan=\"3\"></td><td><span class=\"btn small\">Configure AI App</span></td></tr>\n          <tr><td>6</td><td>\u2014</td><td colspan=\"3\"></td><td><span class=\"btn small\">Configure AI App</span></td></tr>\n          <tr><td>7</td><td>\u2014</td><td colspan=\"3\"></td><td><span class=\"btn small\">Configure AI App</span></td></tr>\n        </table>\n      </div>\n\n    </div>\n  </div>\n</div>\n<figcaption>Video Stream screen</figcaption>\n</div>\n\n      <ol>\n        <li>In the usage display area, the <strong>AI Engine</strong> item shows current usage against the AI Bridge's maximum processing capacity. Since different apps may require different amounts of AI processing, be careful not to configure more than the maximum capacity. The <strong>Video Decoding</strong> item shows current usage against the maximum amount of video the AI Bridge can receive and process from cameras. The <strong>Video Resolution</strong> item shows current usage against the maximum resolution available on the AI Bridge. None of these items can be set beyond their maximum value.</li>\n        <li>The video stream settings area is where you configure information for video streams reachable over the network.</li>\n      </ol>\n\n      <h2>Setting Up Video Stream per Channel</h2>\n      <p>In the video stream list, click the <strong>channel</strong> entry you want to configure.</p>\n      \n<div class=\"figure\">\n<div class=\"modal-mock\" style=\"max-width:520px;margin:0 auto;\">\n  <div class=\"modal-head\">CH 5 <span>&times;</span></div>\n  <div class=\"modal-body\">\n    <div class=\"section-label\">Attribute</div>\n    <div class=\"form-grid\"><span>Channel Name</span><input placeholder=\"Channel Name\" disabled></div>\n    <div class=\"section-label\">Video Source</div>\n    <div class=\"form-grid\">\n      <span>URL</span><input placeholder=\"rtsp://\" disabled>\n      <span>Transport</span><select disabled><option>TCP</option></select>\n      <span>HTTP(S) Port</span><input value=\"0\" disabled>\n      <span>Authentication</span><input type=\"checkbox\" disabled>\n      <span>Username</span><input disabled>\n      <span>Password</span><input disabled>\n    </div>\n    <div class=\"section-label\">Etc</div>\n    <div class=\"form-grid\">\n      <span>Use Cam Speaker</span><span><input type=\"checkbox\" disabled> Connect an additional audio session to transmit sound.</span>\n      <span>Video Buffering</span><select disabled><option>~500ms</option></select>\n    </div>\n  </div>\n  <div class=\"modal-foot\" style=\"justify-content:space-between;\">\n    <span><span class=\"btn small\">Reset</span> <span class=\"btn small\">Reconnect</span></span>\n    <span><span class=\"btn small\">Cancel</span> <span class=\"btn small primary\">Submit</span></span>\n  </div>\n</div>\n<figcaption>Per-channel video stream configuration</figcaption>\n</div>\n\n      <ol>\n        <li>Enter the <strong>channel name</strong>.</li>\n        <li>Enter the camera's <strong>RTSP URL</strong>.</li>\n        <li>Select the transport protocol. The transport protocol specifies which transport-layer protocol is used to retrieve the video.</li>\n        <li>Configure the authentication information required to receive video from the network camera. This is typically the network camera's username and password.</li>\n        <li>If you've installed a speaker on the camera and want to use the audio transmission feature, check <strong>Use Cam Speaker</strong>.</li>\n        <li>Set the maximum video buffering time. If video data doesn't arrive uniformly due to network conditions or the type of camera \u2014 arriving in bursts instead \u2014 the AI Bridge can redistribute it into a uniform stream according to the buffering setting. Since this setting is a maximum, the actual buffering time runs lower than the configured value as long as the camera and network are performing well.</li>\n      </ol>\n\n      <h2>Checking the Video Stream</h2>\n      <p>You can check whether the configured video stream is being received correctly.</p>\n      <p>Click the <strong>Video Preview</strong> button in the header area to view the incoming video.</p>\n      \n<div class=\"figure\" style=\"max-width:320px;\">\n  <div style=\"display:flex;align-items:center;gap:10px;background:#12213f;padding:10px 16px;border-radius:6px;\">\n    <span style=\"background:#2f9e6e;border-radius:10px;padding:1px 8px;color:#fff;font-size:12px;\">Arm</span>\n    <span class=\"btn small\" style=\"outline:2px solid #d64545;\">&#9633; Video Preview</span>\n    <span style=\"color:#cfd6e6;font-size:12px;\">admin &#9660;</span>\n  </div>\n  <figcaption>The Video Preview button in the header</figcaption>\n</div>\n\n\n      <h2>Setting Up Multiple Channels at Once</h2>\n      <p>You can configure the video streams for multiple channels at the same time. The video settings screen supports copy &amp; paste, and features like Apply All make it easy to configure several channels' video streams at once.</p>\n      <p>Click the <strong>Edit Video</strong> button in the video stream settings area.</p>\n      \n<div class=\"figure\" style=\"max-width:340px;\">\n  <span class=\"btn small\">&#128269; Search Cameras</span> <span class=\"btn small primary\" style=\"outline:2px solid #d64545;\">&#9998; Edit Video</span>\n</div>\n\n      <p>On the video settings screen you can configure the name, RTSP URL, transport, and authentication information for every channel at once.</p>\n      <p>Content entered in the <strong>Apply All</strong> row at the top can be applied to every channel by clicking the check button next to each setting.</p>\n      \n<div class=\"figure\">\n<div class=\"modal-mock\" style=\"max-width:640px;margin:0 auto;\">\n  <div class=\"modal-head\">Video Source <span>&times;</span></div>\n  <div class=\"modal-body\">\n    <table class=\"app-table\">\n      <tr><th>Video</th><th>Video Name</th><th>URL</th><th>Transport</th><th>Authentication</th></tr>\n      <tr><td>Apply All</td><td><input value=\"Gate 01\" disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>1</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>2</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>3</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>4</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>5</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>6</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>7</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n      <tr><td>8</td><td><input disabled></td><td><input value=\"rtsp://\" disabled></td><td><select disabled><option>TCP</option></select></td><td><input placeholder=\"Username\" disabled> <input placeholder=\"Password\" disabled></td></tr>\n    </table>\n  </div>\n  <div class=\"modal-foot\" style=\"justify-content:space-between;\">\n    <span class=\"btn small\">Reset</span>\n    <span><span class=\"btn small\">Cancel</span> <span class=\"btn small primary\">Apply</span></span>\n  </div>\n</div>\n<figcaption>Editing all channels' video streams at once</figcaption>\n</div>\n\n      <p>You can search for cameras and configure the streams that way, too.</p>\n      <p>To use the search feature, click the <strong>Search Cameras</strong> button in the video stream settings area.</p>\n      \n<div class=\"figure\" style=\"max-width:340px;\">\n  <span class=\"btn small primary\" style=\"outline:2px solid #d64545;\">&#128269; Search Cameras</span> <span class=\"btn small\">&#9998; Edit Video</span>\n</div>\n\n      <p>ONVIF is a standard for interoperating with physical security equipment. For network cameras that support the ONVIF standard, you can configure the video stream by searching for the camera.</p>\n\n      <h2>Finding Cameras via Search</h2>\n      \n<div class=\"figure\">\n<div class=\"modal-mock\" style=\"max-width:600px;margin:0 auto;\">\n  <div class=\"modal-head\">Search Cameras <span>&times;</span></div>\n  <div class=\"modal-body\">\n    <div style=\"border:1px solid var(--border);border-radius:6px;padding:12px;display:flex;justify-content:space-between;align-items:center;font-size:12.5px;margin-bottom:14px;\">\n      <div>\n        <div>&#10122; Click 'Search Cameras' to auto-detect compatible cameras.</div>\n        <div>&#10123; Log in, get RTSP URLs, and assign to desired channels.</div>\n      </div>\n      <span class=\"btn small primary\" style=\"outline:2px solid #d64545;\">&#128269; Search Cameras</span>\n    </div>\n    <div style=\"border:1px solid var(--border);border-radius:6px;height:140px;\"></div>\n  </div>\n  <div class=\"modal-foot\"><span class=\"btn small\">Cancel</span> <span class=\"btn small primary\">Submit</span></div>\n</div>\n<figcaption>ONVIF camera search \u2014 before searching</figcaption>\n</div>\n\n      <p>After searching for cameras in the ONVIF search popup and entering the authentication information, the list of video streams the camera supports is displayed. Assign the stream you want to analyze to an AI Bridge channel.</p>\n      \n<div class=\"figure\">\n<div class=\"modal-mock\" style=\"max-width:640px;margin:0 auto;\">\n  <div class=\"modal-head\">Search Cameras <span>&times;</span></div>\n  <div class=\"modal-body\">\n    <div style=\"border:1px solid var(--border);border-radius:6px;padding:10px 12px;display:flex;justify-content:space-between;align-items:center;font-size:12px;margin-bottom:14px;\">\n      <div>\n        <div>&#10122; Click 'Search Cameras' to auto-detect compatible cameras.</div>\n        <div>&#10123; Log in, get RTSP URLs, and assign to desired channels.</div>\n      </div>\n      <span class=\"btn small primary\">&#128269; Search Cameras</span>\n    </div>\n    <table class=\"app-table\">\n      <tr><td>QPX_0824M5C &nbsp;192.168.101.191</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n      <tr><td>IPX &nbsp;192.168.101.137</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n      <tr><td>VUHDIP-32 &nbsp;192.168.101.46</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n      <tr><td>CSB2-5M4C-1MPAR7 &nbsp;192.168.101.128</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n      <tr><td>VUHDIP-8-3 &nbsp;192.168.102.8</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n      <tr style=\"outline:2px solid #d64545;\"><td>CSB-8MP-1VKAR5 &nbsp;192.168.103.214</td><td><input value=\"ADMIN\" disabled></td><td><input value=\"&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;\" disabled></td><td><span class=\"btn small primary\">Login</span></td></tr>\n      <tr><td>CSB-8MP-1VKAR5 &nbsp;192.168.103.213</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n      <tr><td>CSB-8MP-1VKAR5 &nbsp;192.168.103.215</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n      <tr><td>NHC-IR22T &nbsp;192.168.101.90</td><td><input placeholder=\"Username\" disabled></td><td><input placeholder=\"Password\" disabled></td><td><span class=\"btn small\">Login</span></td></tr>\n    </table>\n  </div>\n  <div class=\"modal-foot\"><span class=\"btn small\">Cancel</span> <span class=\"btn small primary\">Submit</span></div>\n</div>\n<figcaption>Detected cameras \u2014 logging in to one</figcaption>\n</div>\n\n      \n<div class=\"figure\">\n<div class=\"modal-mock\" style=\"max-width:640px;margin:0 auto;\">\n  <div class=\"modal-head\">Search Cameras <span>&times;</span></div>\n  <div class=\"modal-body\">\n    <table class=\"app-table\">\n      <tr><td rowspan=\"1\">CSB-8MP-1VKAR5 &nbsp;192.168.103.214</td><td colspan=\"3\"></td></tr>\n      <tr><td style=\"padding-left:24px;\">rtsp://ADMIN:&bull;&bull;&bull;&bull;&bull;@192.168.103.214:554/live/main</td><td>1920x1080 / ~15 FPS</td><td colspan=\"2\" style=\"outline:2px solid #d64545;\">\n        <select disabled><option>CH1</option><option>None</option><option>CH2</option><option>CH3</option><option>CH4</option><option>CH5</option><option>CH6</option></select>\n      </td></tr>\n      <tr><td style=\"padding-left:24px;\">rtsp://ADMIN:&bull;&bull;&bull;&bull;&bull;@192.168.103.214:554/live/second</td><td>640x360 / ~30 FPS</td><td><select disabled><option>None</option></select></td></tr>\n      <tr><td>CSB-8MP-1VKAR5 &nbsp;192.168.103.213</td><td><input placeholder=\"Username\" disabled></td><td colspan=\"2\"><span class=\"btn small\">Login</span></td></tr>\n    </table>\n  </div>\n  <div class=\"modal-foot\"><span class=\"btn small\">Cancel</span> <span class=\"btn small primary\">Submit</span></div>\n</div>\n<figcaption>Assigning a discovered RTSP stream to a channel</figcaption>\n</div>\n\n\n      <h2>AI App Configuration</h2>\n      <p>Once a video stream is connected, click the <strong>Configure AI App</strong> button to select the appropriate app and set up event action rules.</p>\n      \n<div class=\"figure\" style=\"max-width:280px;\">\n  <div><span class=\"btn small\">&#128269; Search Cameras</span> <span class=\"btn small\">&#9998; Edit Videos</span></div>\n  <div style=\"margin-top:8px;\"><span class=\"btn small\" style=\"outline:2px solid #d64545;\">Configure AI App</span></div>\n  <div style=\"margin-top:6px;\"><span class=\"btn small\">Configure AI App</span>";
